CREATE FUNCTION "gold"."upsert_market_reading"("p_instrument_id" "text", "p_symbol" "text", "p_name" "text", "p_cls" "text", "p_country_iso3" character, "p_publisher" "text", "p_publisher_code" "text", "p_currency" "text", "p_unit" "text", "p_value" double precision, "p_change_abs" double precision, "p_change_pct" double precision, "p_asof" timestamp with time zone, "p_source" "text") RETURNS "void"
    LANGUAGE "sql"
    AS $$
  ON CONFLICT (instrument_id) DO UPDATE SET
    symbol = EXCLUDED.symbol, name = EXCLUDED.name, cls = EXCLUDED.cls,
    country_iso3 = EXCLUDED.country_iso3, publisher = EXCLUDED.publisher,
    publisher_code = EXCLUDED.publisher_code, currency = EXCLUDED.currency,
    unit = EXCLUDED.unit, active = TRUE, updated_at = NOW();

  ON CONFLICT (instrument_id) DO UPDATE SET
    value = EXCLUDED.value, change_abs = EXCLUDED.change_abs,
    change_pct = EXCLUDED.change_pct, asof = EXCLUDED.asof,
    source = EXCLUDED.source, retrieved_at = NOW();
$$;


--
-- Name: FUNCTION "upsert_market_reading"("p_instrument_id" "text", "p_symbol" "text", "p_name" "text", "p_cls" "text", "p_country_iso3" character, "p_publisher" "text", "p_publisher_code" "text", "p_currency" "text", "p_unit" "text", "p_value" double precision, "p_change_abs" double precision, "p_change_pct" double precision, "p_asof" timestamp with time zone, "p_source" "text"); Type: COMMENT; Schema: gold; Owner: -
--

COMMENT ON FUNCTION "gold"."upsert_market_reading"("p_instrument_id" "text", "p_symbol" "text", "p_name" "text", "p_cls" "text", "p_country_iso3" character, "p_publisher" "text", "p_publisher_code" "text", "p_currency" "text", "p_unit" "text", "p_value" double precision, "p_change_abs" double precision, "p_change_pct" double precision, "p_asof" timestamp with time zone, "p_source" "text") IS 'Idempotent upsert of a catalog row + current quote. Use from every ingest adapter and ad-hoc backfill so instrument/quote stay in sync.';


SET default_tablespace = '';

SET default_table_access_method = "heap";

