--
-- Name: run_bridge; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."run_bridge" AS
 WITH "base_total" AS (
         SELECT "sr_1"."run_id",
            (EXTRACT("year" FROM "ro"."period"))::integer AS "year",
            "ro"."p50" AS "main_block_total"
           FROM ("public"."scenario_run" "sr_1"
             JOIN "public"."run_output" "ro" ON ((("ro"."run_id" = "sr_1"."run_id") AND ("ro"."scenario_code" = 'base'::"text") AND ("ro"."line_code" = 'TOTAL'::"text"))))
        ), "dof_budget" AS (
         SELECT (EXTRACT("year" FROM "de_fiscal_history"."period"))::integer AS "year",
            "de_fiscal_history"."value_aed_m" AS "budget_total"
           FROM "gold"."de_fiscal_history"
          WHERE (("de_fiscal_history"."series_group" = 'dof_budget'::"text") AND ("de_fiscal_history"."series_name" = 'budget_revenue_total'::"text"))
        )
 SELECT "sr"."run_id",
    "years"."year",
    "db"."budget_total",
    "bt"."main_block_total",
        CASE
            WHEN (("db"."budget_total" IS NULL) OR ("bt"."main_block_total" IS NULL)) THEN NULL::double precision
            ELSE ("db"."budget_total" - "bt"."main_block_total")
        END AS "other_blocks_total",
    'DoF general budget open data · data.dubai 35681/726117 + scenario_run Base'::"text" AS "source",
    ("sr"."vintages" ->> 'budget_vintage'::"text") AS "vintage",
    COALESCE(("sr"."vintages" ->> 'bridge_label'::"text"), 'indicative'::"text") AS "label"
   FROM ((("public"."scenario_run" "sr"
     CROSS JOIN LATERAL ( SELECT DISTINCT "dof_budget"."year"
           FROM "dof_budget"
        UNION
         SELECT DISTINCT "base_total"."year"
           FROM "base_total"
          WHERE ("base_total"."run_id" = "sr"."run_id")) "years")
     LEFT JOIN "dof_budget" "db" ON (("db"."year" = "years"."year")))
     LEFT JOIN "base_total" "bt" ON ((("bt"."run_id" = "sr"."run_id") AND ("bt"."year" = "years"."year"))));


