--
-- Name: run_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."run_summary" AS
 SELECT "ro"."run_id",
    "ro"."scenario_code",
    (EXTRACT("year" FROM "ro"."period"))::integer AS "year",
    "ro"."period",
    "ro"."line_code",
    "dl"."family_name",
    "dl"."block",
    "dl"."sort_order",
    "dl"."is_tax",
    "ro"."p10",
    "ro"."p25",
    "ro"."p50",
    "ro"."p75",
    "ro"."p90",
    "ro"."base_p50",
    "ro"."is_nowcast",
    "ro"."unit",
    "ro"."label" AS "line_label",
    "sr"."preset",
    "sr"."cycle",
    "sr"."focus_year",
    "sr"."state",
    "sr"."vintages",
    "sr"."feedback_on",
    "sr"."gate_results",
    "mv"."code" AS "model_code",
    "mv"."version" AS "model_version",
    "mv"."config_name",
    "mv"."label" AS "model_label"
   FROM ((("public"."run_output" "ro"
     JOIN "public"."scenario_run" "sr" ON (("sr"."run_id" = "ro"."run_id")))
     JOIN "public"."model_version" "mv" ON (("mv"."model_version_id" = "sr"."model_version_id")))
     LEFT JOIN "public"."dim_line" "dl" ON (("dl"."line_code" = "ro"."line_code")));


--
-- Name: scenario; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."scenario" (
    "scenario_id" "text" NOT NULL,
    "code" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "created_at" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: signal; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."signal" (
    "id" "text" NOT NULL,
    "headline" "text" NOT NULL,
    "source_url" "text" NOT NULL,
    "source_name" "text" NOT NULL,
    "published_at" timestamp(3) without time zone NOT NULL,
    "sector" "text" NOT NULL,
    "status" "text" DEFAULT 'CANDIDATE'::"text" NOT NULL,
    "analysis" "text",
    "revenue_impact_aed_bn" double precision DEFAULT 0 NOT NULL,
    "expenditure_impact_aed_bn" double precision DEFAULT 0 NOT NULL,
    "d33_objective" "text",
    "d33_impact_score" double precision,
    "confidence" double precision DEFAULT 0.5 NOT NULL,
    "horizon_years" integer DEFAULT 1 NOT NULL,
    "document_id" "text",
    "reviewed_by_id" "text",
    "created_at" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "rule_impact_aed_bn" double precision,
    "engine_preset" "text",
    "pinned_vintage" "text",
    "engine_run_id" "text",
    "engine_run_state" "text",
    "engine_impact_aed_bn" double precision,
    "assessed_at" timestamp with time zone,
    "ssot_market_news_id" "text",
    "promoted_by" "text"
);


--
-- Name: signal_training_example; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."signal_training_example" (
    "id" "text" NOT NULL,
    "news_id" "text" NOT NULL,
    "headline" "text" NOT NULL,
    "lede" "text",
    "source_name" "text",
    "category" "text",
    "sector" "text",
    "direction" "text",
    "label" "text" NOT NULL,
    "rationale" "text",
    "created_by_id" "text",
    "created_at" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "signal_training_example_label_chk" CHECK (("label" = ANY (ARRAY['positive'::"text", 'negative'::"text"])))
);


--
-- Name: source; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."source" (
    "code" "text" NOT NULL,
    "name" "text" NOT NULL,
    "kind" "text" NOT NULL,
    "url" "text",
    "licence" "text",
    "refresh" "text",
    "cadence_cron" "text",
    "description" "text",
    "enabled" boolean DEFAULT true NOT NULL,
    "history_from" integer,
    "last_error" "text",
    "last_fetched_at" timestamp(3) without time zone,
    "last_rows" integer,
    "last_status" "text",
    "next_expected_release" timestamp(3) without time zone,
    "tier" "text"
);


--
-- Name: user; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."user" (
    "id" "text" NOT NULL,
    "email" "text" NOT NULL,
    "name" "text" NOT NULL,
    "role" "text" NOT NULL,
    "created_at" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "password_hash" "text" NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "last_login_at" timestamp(3) without time zone
);


--
-- Name: version; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."version" (
    "id" "text" NOT NULL,
    "run_id" "text" NOT NULL,
    "cycle" "text" NOT NULL,
    "label" "text" NOT NULL,
    "is_official" boolean DEFAULT false NOT NULL,
    "locked_at" timestamp(3) without time zone,
    "created_at" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


